CREATE OR REPLACE FUNCTION private.closure_redaction_patch_v5(r text, t jsonb, a uuid, g uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
declare p jsonb:='{}';k text;h text;ag public.agreements;terms jsonb;
begin
 if r is null or t is null or a is null or g is null or not(r=any(private.closure_redaction_relations_v5()))
 then raise exception 'ERASURE_RELATION_NOT_ADMITTED';end if;
 if r='public.agreement_invalidations_v1' then
  return jsonb_build_object('operation','DELETE','patch','{}'::jsonb);end if;
 h:=encode(extensions.digest(convert_to('AF-D22:ERASED:'||r||':'||coalesce(t->>'id',t->>'client_request_id',t->>'conversation_id',t->>'review_id',t->>'account_id','subject'),'UTF8'),'sha256'),'hex');
 -- Support command receipts are metadata only. A related scoped case keeps its
 -- exact recovery/hash contract until that exception is resolved; no narrative
 -- is copied into the redaction ledger. Cancelled opaque tombstones stay usable.
 if r in('private.support_commands_v5','private.support_grant_commands_v5') then return null;end if;
 if r in('public.ai_conversations','public.ai_messages','public.ai_structured_facts','public.ai_action_proposals',
  'private.ai_need_turn_commands','private.worker_ai_turns','private.worker_ai_sessions','private.ai_task_reviews','private.worker_ai_reviews','private.need_draft_save_commands')
 and exists(select 1 from private.retention_holds where account_id=a and active and conversation_id=
  case when r='public.ai_conversations' then (t->>'id')::uuid else (t->>'conversation_id')::uuid end) then return null;end if;
 if r='private.ai_task_review_commands' and exists(select 1 from private.ai_task_reviews v join private.retention_holds h on h.account_id=v.account_id and h.conversation_id=v.conversation_id and h.active
  where v.account_id=a and v.id=(t->>'review_id')::uuid) then return null;end if;
 if r='private.worker_ai_saves' and exists(select 1 from private.worker_ai_reviews v join private.retention_holds h on h.account_id=v.account_id and h.conversation_id=v.conversation_id and h.active
  where v.account_id=a and v.id=(t->>'review_id')::uuid) then return null;end if;
 if r='public.ai_structured_facts' then
  if t->'superseded_by'<>'null'::jsonb then return jsonb_build_object('operation','UPDATE','patch',jsonb_build_object('superseded_by',null));end if;
  if exists(select 1 from public.ai_structured_facts where superseded_by=(t->>'id')::uuid) then return null;end if;
 end if;
 if r in('public.ai_messages','public.ai_structured_facts','public.ai_action_proposals',
  'public.need_sensitive','public.need_geography','public.need_requirement_details',
  'private.data_export_artifacts','public.notification_push_attempts','public.notification_deliveries',
  'public.notification_push_devices','public.notification_preferences','public.opportunity_deliveries',
  'private.dispatch_schedule','public.access_grants','public.profile_availability_rules','public.profile_availability_windows',
  'public.worker_match_preferences','private.worker_calendar_events','private.worker_calendar_serialization',
  'private.support_read_markers_v5','private.group_message_visibility_v5') then
  if r='private.data_export_artifacts' and exists(select 1 from storage.objects where bucket_id='data-export-artifacts' and name=t->>'object_path')
  then raise exception 'ERASURE_STORAGE_NOT_CLEAN';end if;
  return jsonb_build_object('operation','DELETE','patch','{}'::jsonb);
 end if;
 if r in('private.owned_media_assets','private.agreement_photo_uploads_v5') then
  if t->>'dispatch_state'='DISPATCHING' then raise exception 'ERASURE_PRODUCER_UNSETTLED';end if;
  if private.closure_erasure_media_protected_v5(a,t->>'storage_path') then return null;end if;
  if exists(select 1 from storage.objects where bucket_id='profile-media' and name=t->>'storage_path') then raise exception 'ERASURE_STORAGE_NOT_CLEAN';end if;
  return jsonb_build_object('operation','DELETE','patch','{}'::jsonb);
 end if;
 if r='public.app_accounts' then p:=jsonb_build_object('email','','phone','','full_name','','city','');
 elsif r='public.app_profiles' then p:=jsonb_build_object('display_name','','city','','headline','','bio','','avatar_path',null,
  'portfolio','[]'::jsonb,'skills','[]'::jsonb,'tools','[]'::jsonb,'licenses','[]'::jsonb,'vehicles','[]'::jsonb,'exclusions','[]'::jsonb,
  'years_experience',0,'radius_km',1,'available_now',false,'available_now_expires_at',null,'team_capacity',1,
  'minimum_fee_rsd',0,'rating_requester',null,'rating_worker',null,'operating_country_code',null,'profile_status','CLOSED');
 elsif r='public.needs' then p:=jsonb_build_object('title','Obrisan zadatak','description','Sadržaj uklonjen pri zatvaranju naloga.','category','OBRISANO',
  'approximate_city','','approximate_area','','approximate_lat',null,'approximate_lng',null,
  'starts_at',null,'ends_at',null,'required_skills','[]'::jsonb,'required_tools','[]'::jsonb,'required_vehicles','[]'::jsonb,'required_licenses','[]'::jsonb,
  'public_photo_paths','[]'::jsonb,'requester_price_rsd',null,'response_deadline',null,'urgent',false,
  'urgent_activated_at',null,'urgent_expires_at',null,'urgent_policy_version',null,'remaining_search_close_reason',null);
 elsif r in('private.ai_task_reviews','private.worker_ai_reviews') then p:=jsonb_build_object('envelope',jsonb_build_object('erasedBy','AF-D22'));
 elsif r='private.worker_ai_sessions' then p:=jsonb_build_object('candidate',jsonb_build_object('erasedBy','AF-D22'));
 elsif r='private.ai_task_review_commands' then
  foreach k in array array['evaluation_binding','evaluation','published'] loop
   if t->k<>'null'::jsonb then p:=p||jsonb_build_object(k,jsonb_build_object('erasedBy','AF-D22'));end if;
  end loop;
 elsif r='private.need_revision_events' then p:=jsonb_build_object('previous_material_snapshot',jsonb_build_object('erasedBy','AF-D22'),'new_material_snapshot',jsonb_build_object('erasedBy','AF-D22'));
 elsif r='public.data_export_requests' then p:=jsonb_build_object('active_export_attempt_id',null,
  'export_revoked_at',coalesce(nullif(t->'export_revoked_at','null'::jsonb),to_jsonb((select requested_at from private.closure_executions_v5 where generation=g and account_id=a))));
 elsif r='private.need_publication_decisions' then p:=jsonb_build_object('public_geography_snapshot',jsonb_build_object('erasedBy','AF-D22'),'public_media_refs','[]'::jsonb,'reviewer_provenance','{}'::jsonb,'service_provenance',jsonb_build_object('erasedBy','AF-D22'));
 elsif r='private.preselection_qa_questions' then p:=jsonb_build_object('question_text','Sadržaj uklonjen pri zatvaranju naloga.');
 elsif r='private.preselection_qa_answer_versions' then p:=jsonb_build_object('answer_text','Sadržaj uklonjen pri zatvaranju naloga.');
 elsif r in('private.preselection_qa_policy_decisions','private.preselection_qa_materiality_decisions') then
  if exists(select 1 from private.qa_ai_commands q where q.account_id<>a and
   (case when r='private.preselection_qa_policy_decisions' then q.policy_decision_id else q.materiality_decision_id end)=(t->>'id')::uuid
   and not exists(select 1 from private.closure_executions_v5 e join private.closure_actions_v5 ac on ac.generation=e.generation
    where e.account_id=q.account_id and ac.kind='RELATIONAL_REDACT' and ac.state='VERIFIED')) then return null;end if;
  p:=jsonb_build_object('service_provenance',jsonb_build_object('erasedBy','AF-D22'));
 elsif r='private.response_application_snapshots' then p:=jsonb_build_object('worker_skills','[]'::jsonb,'worker_tools','[]'::jsonb,'worker_licenses','[]'::jsonb,'worker_vehicles','[]'::jsonb);
 elsif r in('public.marketplace_responses','public.marketplace_response_versions') then
  if exists(select 1 from public.agreements x where x.selected_response_id=coalesce(t->>'response_id',t->>'id')::uuid and private.closure_erasure_agreement_protected_v5(x.id)) then return null;end if;
  p:=jsonb_build_object('scope_note','');if t?'bounded_message' then p:=p||jsonb_build_object('bounded_message','');end if;
 elsif r='public.agreement_messages' then
  -- A selected Support copy survives in its immutable scoped snapshot. The
  -- original ordinary chat row does not need the same plaintext forever.
  p:=jsonb_build_object('body','Sadržaj uklonjen pri zatvaranju naloga.','photo_asset_ids','[]'::jsonb);
 elsif r='private.group_messages_v5' then p:=jsonb_build_object('body','Sadržaj uklonjen pri zatvaranju naloga.');
 elsif r in('public.agreement_versions','public.agreement_change_proposals') then
  if private.closure_erasure_agreement_protected_v5((t->>'agreement_id')::uuid) then return null;end if;
  k:=case when r='public.agreement_versions' then 'terms' else 'proposed_terms' end;
  if exists(select 1 from private.closure_scope_sources_v5 where account_id=a and generation=g and agreement_id=(t->>'agreement_id')::uuid
   and source_kind=case when r='public.agreement_versions' then 'VERSION' else 'PROPOSAL' end
   and source_id=case when r='public.agreement_versions' then t->>'version' else t->>'id' end and scope_author=a) then
   terms:=(t->k)||jsonb_build_object('scope_note','');p:=jsonb_build_object(k,terms);
  end if;
  if r='public.agreement_change_proposals' and t->>'proposed_by_account_id'=a::text then p:=p||jsonb_build_object('reason','Sadržaj uklonjen pri zatvaranju naloga.');end if;
  if p='{}'::jsonb then return null;end if;
 elsif r='public.agreement_execution' then
  -- The source problem itself is an unresolved evidence exception.
  if t->'problem_opened_at'<>'null'::jsonb then return null;end if;
  p:=jsonb_build_object('problem_narrative',null);
 elsif r='private.agreement_location_points' then return jsonb_build_object('operation','DELETE','patch','{}'::jsonb);
 elsif r='public.user_activity_events' then
  if t->>'recipient_user_id'=a::text then return jsonb_build_object('operation','DELETE','patch','{}'::jsonb);end if;
  p:=jsonb_build_object('payload',jsonb_build_object('erasedBy','AF-D22'));
 elsif r='private.marketplace_audit_log' then p:=jsonb_build_object('detail',jsonb_build_object('erasedBy','AF-D22'));
 elsif r='private.retention_holds' then
  if t->'active'='true'::jsonb then return null;end if;
  p:=jsonb_build_object('hold_key','AF-D22:'||(t->>'id'));
 elsif r='private.ai_test_accounts_v5' then
  if t->'retired_at'='null'::jsonb then p:=jsonb_build_object('retired_at',(select requested_at from private.closure_executions_v5 where generation=g and account_id=a));end if;
 elsif r='private.support_operator_grants_v5' then
  if t->'active'='true'::jsonb then p:=jsonb_build_object('active',false,'revision',(t->>'revision')::integer+1,'updated_at',(select requested_at from private.closure_executions_v5 where generation=g and account_id=a));end if;
 end if;
 -- Content-derived request hashes are no longer original-content proofs after
 -- erasure. Policy/document/source-program digests and charged units are kept.
 foreach k in array array['request_hash','input_hash','input_sha256','text_sha256','semantic_hash','content_fingerprint',
  'question_fingerprint','answer_fingerprint','context_hash','body_hash','body_sha256','completion_hash','source_hash','base_hash',
  'canonical_fingerprint','private_materiality_marker','content_hash','evaluation_result_hash','need_edit_base_fingerprint'] loop
  if t?k and jsonb_typeof(t->k)='string' then p:=p||jsonb_build_object(k,h);end if;
 end loop;
 -- These JSON command results are private source copies, not immutable legal
 -- terms. Keep identity/state columns for anti-replay, never old narrative JSON.
 if r in('private.requester_identity_commands','private.worker_ai_saves','private.need_draft_save_commands',
  'private.ai_need_turn_commands','private.worker_ai_turns','private.qa_ai_commands',
  'private.need_edit_commands','private.need_publish_commands','private.response_submit_commands','private.response_withdraw_commands',
  'private.response_revision_resolution_commands','private.remaining_search_close_commands','private.preselection_qa_commands',
  'private.account_block_commands','private.retention_jobs','private.support_commands_v5','private.support_grant_commands_v5') then
  foreach k in array array['receipt','result'] loop
   if t?k and t->k<>'null'::jsonb then p:=p||jsonb_build_object(k,jsonb_build_object('erasedBy','AF-D22'));end if;
  end loop;
 end if;
 -- An operator's note about a person is not audit metadata the subject must live with. The
 -- lineage class, its revision and its timestamps stay; the free text becomes a fixed code.
 if r in('private.account_lineage_v5','private.account_lineage_events_v5') then
  p:=p||jsonb_build_object('reason','CLOSURE_ERASED_OPERATOR_NOTE','source_ref','CLOSURE_ERASED_SOURCE_REF');
 end if;
 if p='{}'::jsonb or t@>p then return null;end if;
 return jsonb_build_object('operation','UPDATE','patch',p);
end $function$

CREATE OR REPLACE FUNCTION private.closure_blockers_v5(a uuid)
 RETURNS text[]
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
declare codes text[]:='{}';
begin
 if exists(select 1 from private.retention_holds where account_id=a and active) then codes:=array_append(codes,'RETENTION_HOLD');end if;
 if exists(select 1 from public.agreements where (requester_account_id=a or worker_account_id=a) and status not in('COMPLETED','CANCELLED')) then codes:=array_append(codes,'ACTIVE_AGREEMENT');end if;
 if exists(select 1 from public.needs where requester_account_id=a and status in('PUBLISHED','SELECTION','ACTIVE')) then codes:=array_append(codes,'OPEN_TASK');end if;
 if exists(select 1 from public.marketplace_responses where worker_account_id=a and status in('SUBMITTED','DELIVERED','VIEWED','SHORTLISTED')) then codes:=array_append(codes,'ACTIVE_APPLICATION');end if;
 if exists(select 1 from private.ai_need_turn_commands where account_id=a and state='PROCESSING')
 or exists(select 1 from private.worker_ai_turns where account_id=a and state='PROCESSING')
 or exists(select 1 from private.qa_ai_commands where account_id=a and state='PROCESSING')
 or exists(select 1 from private.retention_jobs where account_id=a and status='CLAIMED')
 or exists(select 1 from public.data_export_requests where account_id=a and status='PROCESSING') then codes:=array_append(codes,'PENDING_WORKFLOW');end if;
 if exists(select 1 from private.owned_media_assets where account_id=a and dispatch_state='DISPATCHING')
 or exists(select 1 from private.data_export_artifacts where account_id=a and verified_at is null) then codes:=array_append(codes,'STORAGE_PRODUCER_UNSETTLED');end if;
 -- A foreign bucket or a legacy object without an authoritative owner-prefix
 -- cannot become an arbitrary service-role deletion target.
 if exists(select 1 from storage.objects where (owner_id=a::text or split_part(name,'/',1)=a::text)
 and (bucket_id not in('profile-media','data-export-artifacts') or split_part(name,'/',1)<>a::text or name~'(^|/)[.][.](/|$)' or strpos(name,chr(92))>0)) then codes:=array_append(codes,'STORAGE_INVENTORY_UNSUPPORTED');end if;
 if private.media_owner_protected_v5(a) then codes:=array_append(codes,'MEDIA_EVIDENCE_POLICY_NOT_READY');end if;
 if exists(select 1 from private.support_cases_v5 where account_id=a) then codes:=array_append(codes,'SUPPORT_RETENTION_POLICY_NOT_READY');end if;
 if exists(select 1 from private.agreement_photo_uploads_v5 where account_id=a and dispatch_state='DISPATCHING') then codes:=array_append(codes,'MEDIA_UPLOAD_PENDING');end if;
 return codes;
end $function$

CREATE OR REPLACE FUNCTION public.rpc_start_account_closure_execution(p_expected_user_id uuid, p_request_id uuid, p_expected_revision integer, p_client_request_id uuid, p_policy_sha256 text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
declare u uuid:=auth.uid();b jsonb;r private.account_closure_requests;e private.closure_executions_v5;c private.closure_start_commands_v5;h text;receipt jsonb;redaction_id uuid;begin
 if u is null or u is distinct from p_expected_user_id or auth.role() is distinct from 'authenticated' then raise exception 'AUTH_CONTEXT_CHANGED' using errcode='42501';end if;
 if p_request_id is null or p_client_request_id is null or p_expected_revision is null or p_expected_revision<1 or p_expected_revision>=2147483646 or coalesce(p_policy_sha256,'')!~'^[a-f0-9]{64}$' then raise exception 'CLOSURE_INPUT_INVALID' using errcode='22023';end if;
 perform private.closure_erasure_lock_v5(u);
 h:=encode(extensions.digest(jsonb_build_array(u,p_request_id,p_expected_revision,p_policy_sha256)::text,'sha256'),'hex');
 select * into c from private.closure_start_commands_v5 where account_id=u and client_request_id=p_client_request_id;
 if found then if c.input_sha256<>h then raise exception 'REQUEST_ID_REUSED' using errcode='22023';end if;return c.receipt||jsonb_build_object('idempotentReplay',true);end if;
 -- Exact existing metadata replay survives Auth erasure. Only a fresh start
 -- requires a still-live human session, as in every narrative-producing seam.
 perform private.support_auth_v5(p_expected_user_id);
 select * into r from private.account_closure_requests where account_id=u;
 if r.id is distinct from p_request_id or r.revision is distinct from p_expected_revision then raise exception 'CLOSURE_REVISION_CONFLICT' using errcode='PT409';end if;
 if private.closure_account_restricted(u) then raise exception 'ACCOUNT_CLOSING' using errcode='42501';end if;
 b:=private.closure_erasure_binding_v5();
 if b is null or b->>'sha256' is distinct from p_policy_sha256 then raise exception 'CLOSURE_POLICY_NOT_READY' using errcode='55000';end if;
 if cardinality(private.closure_erasure_hard_blockers_v5(u))>0 then raise exception 'CLOSURE_BLOCKED' using errcode='55000';end if;
 insert into private.closure_executions_v5(account_id,request_id,policy_id,policy_sha256,binding) values(u,r.id,null,p_policy_sha256,b) returning * into e;
 update private.account_closure_requests set state='EXECUTING',revision=revision+1,updated_at=clock_timestamp() where account_id=u;
 -- Freeze field attribution before any hash/content is changed. Only source
 -- identities are retained here; no free text or original-content hash copy.
 insert into private.closure_scope_sources_v5(account_id,generation,agreement_id,source_kind,source_id,scope_author)
 select u,e.generation,v.agreement_id,'VERSION',v.version::text,private.closure_erasure_scope_author_v5(v.agreement_id,v.version)
 from public.agreement_versions v join public.agreements ag on ag.id=v.agreement_id where u in(ag.requester_account_id,ag.worker_account_id)
 union all
 select u,e.generation,p.agreement_id,'PROPOSAL',p.id::text,
 coalesce((select ss.scope_author from private.closure_scope_sources_v5 ss join private.closure_executions_v5 ce on ce.generation=ss.generation
  where ss.agreement_id=p.agreement_id and ss.source_kind='PROPOSAL' and ss.source_id=p.id::text and ss.scope_author is not null order by ce.requested_at,ss.generation limit 1),
 case when jsonb_typeof(p.proposed_terms->'scope_note') is distinct from 'string' or v.agreement_id is null then null
  when p.proposed_terms->'scope_note' is not distinct from v.terms->'scope_note' then private.closure_erasure_scope_author_v5(p.agreement_id,p.base_version) else p.proposed_by_account_id end
 )
 from public.agreement_change_proposals p join public.agreements ag on ag.id=p.agreement_id left join public.agreement_versions v on v.agreement_id=p.agreement_id and v.version=p.base_version where u in(ag.requester_account_id,ag.worker_account_id);
 insert into private.closure_actions_v5(generation,account_id,kind,bucket,object_path)
 select e.generation,u,'STORAGE_DELETE',x.bucket,x.path from (
  select bucket_id bucket,name path from storage.objects where split_part(name,'/',1)=u::text
  union select 'profile-media',storage_path from private.owned_media_assets where account_id=u and storage_path is not null
  union select 'profile-media',storage_path from private.agreement_photo_uploads_v5 where account_id=u and storage_path is not null
  union select 'data-export-artifacts',object_path from private.data_export_artifacts where account_id=u) x
 where x.bucket<>'profile-media' or not private.closure_erasure_media_protected_v5(u,x.path);
 insert into private.closure_actions_v5(generation,account_id,kind) values(e.generation,u,'RELATIONAL_REDACT') returning id into redaction_id;
 insert into private.closure_redaction_steps_v5(action_id,account_id,generation,ordinal,relation_name)
 select redaction_id,u,e.generation,ord,rn from unnest(private.closure_redaction_relations_v5()) with ordinality x(rn,ord);
 insert into private.closure_actions_v5(generation,account_id,kind) values(e.generation,u,'AUTH_IDENTITY_ERASE');
 receipt:=jsonb_build_object('accountId',u,'requestId',r.id,'generation',e.generation,'state','EXECUTING','clientRequestId',p_client_request_id,'policySha256',p_policy_sha256,'idempotentReplay',false,'authoritative',true);
 insert into private.closure_start_commands_v5 values(u,p_client_request_id,h,receipt);return receipt;
end $function$

CREATE OR REPLACE FUNCTION private.support_reference_v5(a uuid, v jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
declare k text;i uuid;rev integer;n public.needs;ag public.agreements;m public.agreement_messages;gm private.group_messages_v5;
 review private.ai_task_reviews;sr private.safety_reports;content jsonb;facts jsonb;resolution jsonb;paths jsonb;media jsonb;media_owner uuid;begin
 if jsonb_typeof(v) is distinct from 'object' or v-array['kind','id','revision']<>'{}' or not(v?&array['kind','id','revision'])
 or jsonb_typeof(v->'kind') is distinct from 'string' or jsonb_typeof(v->'id') is distinct from 'string'
 or coalesce(v->>'id','')!~'^[a-f0-9]{8}(-[a-f0-9]{4}){3}-[a-f0-9]{12}$'
 or (v->'revision'<>'null' and (jsonb_typeof(v->'revision')<>'number' or (v->>'revision')!~'^[1-9][0-9]{0,9}$')) then raise exception 'SUPPORT_REFERENCE_INVALID' using errcode='22023';end if;
 k:=v->>'kind';i:=(v->>'id')::uuid;rev:=(v->>'revision')::integer;
 perform private.closure_support_source_fence_v5(a,k,i);
 if k='TASK' then
  select * into n from public.needs where id=i for share;
  if not found or not(n.requester_account_id=a or n.status in('PUBLISHED','SELECTION') or rls_private.need_participant_can_read(n.id)) then raise exception 'SUPPORT_REFERENCE_NOT_AVAILABLE' using errcode='42501';end if;
  if n.revision is distinct from rev then raise exception 'SUPPORT_REFERENCE_STALE' using errcode='PT409';end if;
  content:=jsonb_build_object('title',n.title,'description',n.description,'status',n.status,'createdAt',n.created_at,'executionMode',n.execution_location_mode,'countryCode',n.task_country_code,'submitterRole',case when n.requester_account_id=a then 'REQUESTER' else 'READER' end);
  media_owner:=n.requester_account_id;paths:=to_jsonb(n.public_photo_paths);
 elsif k='AGREEMENT' then
  select * into ag from public.agreements where id=i for share;
  if not found or a not in(ag.requester_account_id,ag.worker_account_id) then raise exception 'SUPPORT_REFERENCE_NOT_AVAILABLE' using errcode='42501';end if;
  if ag.current_version is distinct from rev then raise exception 'SUPPORT_REFERENCE_STALE' using errcode='PT409';end if;
  content:=jsonb_build_object('needId',ag.need_id,'status',ag.status,'createdAt',ag.created_at,'submitterRole',case when a=ag.requester_account_id then 'REQUESTER' else 'WORKER' end);
 elsif k='AGREEMENT_MESSAGE' then
  select * into m from public.agreement_messages where id=i;
  select * into ag from public.agreements where id=m.agreement_id;
  if ag.id is null or a not in(ag.requester_account_id,ag.worker_account_id) then raise exception 'SUPPORT_REFERENCE_NOT_AVAILABLE' using errcode='42501';end if;
  if m.agreement_version is distinct from rev then raise exception 'SUPPORT_REFERENCE_STALE' using errcode='PT409';end if;
  -- Bilateral historical reads remain available to the two participants. A
  -- selected message never imports adjacent messages or private Agreement terms.
  content:=jsonb_build_object('agreementId',m.agreement_id,'body',m.body,'createdAt',m.created_at,'mine',m.sender_account_id=a);
  if cardinality(m.photo_asset_ids)>0 then
   if exists(select 1 from unnest(m.photo_asset_ids)x left join private.agreement_photo_uploads_v5 p on p.id=x where p.id is null or p.attached_message_id is distinct from m.id or p.state<>'READY') then raise exception 'SUPPORT_MEDIA_REFERENCE_NOT_AVAILABLE' using errcode='55000';end if;
   content:=content||jsonb_build_object('media',(select jsonb_agg(jsonb_build_object('assetId',p.id,'sha256',p.sanitized_sha256,'width',p.width,'height',p.height) order by ord)
    from unnest(m.photo_asset_ids) with ordinality x(id,ord) join private.agreement_photo_uploads_v5 p on p.id=x.id));
  end if;
 elsif k='GROUP_MESSAGE' then
  select * into gm from private.group_messages_v5 where id=i;
  if not found or rev is not null or not exists(select 1 from private.group_message_visibility_v5 where message_id=i and account_id=a)
  or not exists(select 1 from private.group_conversations_v5 g where g.id=gm.group_id and private.group_member_v5(g,a)) then raise exception 'SUPPORT_REFERENCE_NOT_AVAILABLE' using errcode='42501';end if;
  content:=jsonb_build_object('groupId',gm.group_id,'sequence',gm.sequence::text,'body',gm.body,'createdAt',gm.created_at,'mine',gm.sender_account_id=a);
 elsif k='TASK_REVIEW' then
  select * into review from private.ai_task_reviews where id=i and account_id=a;
  if not found or rev is not null then raise exception 'SUPPORT_REFERENCE_NOT_AVAILABLE' using errcode='42501';end if;
  select coalesce(jsonb_agg(x),'[]') into facts from jsonb_array_elements(review.envelope->'publicProjection') x where x->>'key' not in('need.exact_address','need.access_notes','need.resolved_location','need.public_photo_paths');
  content:=jsonb_build_object('draftId',review.envelope->'draftId','draftRevision',review.envelope->'draftRevision','displayedContentDigest',review.envelope->'displayedContentDigest',
   'publicFacts',private.data_export_task_facts_v5(facts),'safety',review.envelope->'safety','createdAt',review.created_at,
   'policy',jsonb_build_object('bundleId',review.policy_binding->'bundleId','version',review.policy_binding->'version','contentSha256',review.policy_binding->'contentSha256'),
   'evaluation',(select jsonb_build_object('kind',c.evaluation->'kind','outcome',c.evaluation#>'{decision,outcome}','safeReasonCodes',c.evaluation#>'{decision,safeReasonCodes}') from private.ai_task_review_commands c where c.review_id=i));
  media_owner:=a;select x->'value' into paths from jsonb_array_elements(review.envelope->'publicProjection') x where x->>'key'='need.public_photo_paths';paths:=coalesce(paths,'[]');
 elsif k='SAFETY_REPORT' then
  select * into sr from private.safety_reports where id=i and reporter_account_id=a;
  if not found or rev is not null then raise exception 'SUPPORT_REFERENCE_NOT_AVAILABLE' using errcode='42501';end if;
  -- Narrative remains solely in safety_reports; only its exact owned reference.
  content:=jsonb_build_object('category',sr.category,'needId',sr.need_id,'agreementId',sr.agreement_id,'createdAt',sr.created_at);
 else raise exception 'SUPPORT_REFERENCE_INVALID' using errcode='22023';end if;
 if media_owner is not null then
  perform pg_advisory_xact_lock(private.media_evidence_key_v5(media_owner));
  resolution:=private.resolve_media_snapshot_v5(media_owner,coalesce(paths,'[]'));
  if resolution->'resolved' is distinct from 'true'::jsonb then raise exception 'SUPPORT_MEDIA_REFERENCE_NOT_AVAILABLE' using errcode='55000';end if;
  select coalesce(jsonb_agg(jsonb_build_object('assetId',x->'assetId','sha256',x->'sha256','width',x->'width','height',x->'height') order by x->>'assetId'),'[]') into media from jsonb_array_elements(resolution->'assets') x;
  content:=content||jsonb_build_object('media',media);
 end if;
 return jsonb_build_object('kind',k,'id',i,'revision',rev,'content',content);
end $function$

CREATE OR REPLACE FUNCTION private.data_export_policy_binding()
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
declare p private.retention_policy_sets; m jsonb; d jsonb; c jsonb; seen text[]:='{}'; f jsonb; fields text[]; refs jsonb; privacy private.legal_document_versions; v_now timestamptz:=clock_timestamp();
begin
 select * into p from private.retention_policy_sets where retired_at is null and effective_at<=v_now;
 if not found then return null; end if;
 m:=p.export_delivery;
 if jsonb_typeof(m) is distinct from 'object' or m-ARRAY['schemaVersion','projectionVersion','projectionSha256','privacyDocumentId','privacyContentSha256','contentSha256','artifactLifetimeSeconds','snapshotLifetimeSeconds','downloadLifetimeSeconds','cleanupMode','snapshotCleanupMode','datasets']<>'{}'::jsonb
 or not(m ?& ARRAY['schemaVersion','projectionVersion','projectionSha256','privacyDocumentId','privacyContentSha256','contentSha256','artifactLifetimeSeconds','snapshotLifetimeSeconds','downloadLifetimeSeconds','cleanupMode','snapshotCleanupMode','datasets'])
 or m->>'schemaVersion' is distinct from 'USKOCI_EXPORT_DELIVERY_V2' or m->>'projectionVersion' is distinct from 'OWN_ACCOUNT_V5_8'
 or jsonb_typeof(m->'projectionSha256') is distinct from 'string' or coalesce(m->>'projectionSha256','')!~'^[a-f0-9]{64}$'
 or m->>'projectionSha256' is distinct from private.data_export_projection_sha_v5()
 or m->>'cleanupMode' is distinct from 'DELETE_EXPORT_COPY' or m->>'snapshotCleanupMode' is distinct from 'DELETE_TEMP_SNAPSHOT'
 or coalesce(m->>'privacyDocumentId','')!~'^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
 or coalesce(m->>'privacyContentSha256','')!~'^[0-9a-f]{64}$' or coalesce(m->>'contentSha256','')!~'^[0-9a-f]{64}$'
 or m->>'contentSha256' is distinct from encode(extensions.digest(convert_to((m-'contentSha256')::text,'UTF8'),'sha256'),'hex') then return null; end if;
 foreach fields slice 1 in array ARRAY[ARRAY['artifactLifetimeSeconds','2592000'],ARRAY['snapshotLifetimeSeconds','2592000'],ARRAY['downloadLifetimeSeconds','900']] loop
   if jsonb_typeof(m->fields[1]) is distinct from 'number' or (m->>fields[1])!~'^[1-9][0-9]*$' or (m->>fields[1])::numeric>(fields[2])::numeric then return null; end if;
 end loop;
 if (m->>'downloadLifetimeSeconds')::integer>(m->>'artifactLifetimeSeconds')::integer then return null; end if;
 select * into privacy from private.legal_document_versions where id=(m->>'privacyDocumentId')::uuid and document_kind='PRIVACY' and is_active and retired_at is null and effective_at<=v_now and content_sha256=m->>'privacyContentSha256';
 if not found then return null; end if;
 if exists(select 1 from private.retention_data_classes dc where dc.active and dc.required and (not exists(select 1 from private.retention_policy_rules r where r.policy_id=p.id and r.data_class=dc.code) or not exists(select 1 from jsonb_array_elements(private.data_export_dataset_catalog()) v where v->>'dataClass'=dc.code))) then return null; end if;
 if jsonb_typeof(m->'datasets') is distinct from 'array' or jsonb_array_length(m->'datasets')<>51 then return null; end if;
 for d in select value from jsonb_array_elements(m->'datasets') loop
   if jsonb_typeof(d) is distinct from 'object' or jsonb_typeof(d->'key') is distinct from 'string' or d->>'key'=any(seen) then return null; end if;
   select value into c from jsonb_array_elements(private.data_export_dataset_catalog()) where value->>'key'=d->>'key';
   if not found then return null; end if;seen:=array_append(seen,d->>'key');
   if d->>'mode'='EXCLUDE' then
     if d-ARRAY['key','mode','reasonCode']<>'{}'::jsonb or not(d ?& ARRAY['key','mode','reasonCode']) or jsonb_typeof(d->'reasonCode') is distinct from 'string' or d->>'reasonCode'!~'^[A-Z][A-Z0-9_]{0,63}$' or d->>'key'='account' then return null; end if;
   elsif d->>'mode'='INCLUDE' then
     if d-ARRAY['key','mode','fields']<>'{}'::jsonb or not(d ?& ARRAY['key','mode','fields']) or jsonb_typeof(d->'fields') is distinct from 'array' then return null; end if;
     if jsonb_array_length(d->'fields')<1 or jsonb_array_length(d->'fields')>64 then return null; end if;fields:='{}';
     for f in select value from jsonb_array_elements(d->'fields') loop
       if jsonb_typeof(f)<>'string' or not((c->'fields') ? (f#>>'{}')) or f#>>'{}'=any(fields) then return null; end if; fields:=array_append(fields,f#>>'{}');
     end loop;
     if d->>'key'='account' and not('id'=any(fields)) then return null; end if;
     if d->>'key' in('mediaMetadata','ownedMediaAssets','ownAgreementPhotos','ownSupportEvidence') and not('bytesIncluded'=any(fields)) then return null; end if;
   else return null; end if;
 end loop;
 select coalesce(jsonb_agg(to_jsonb(r) order by data_class),'[]'::jsonb) into refs from private.retention_policy_rules r where policy_id=p.id;
 return jsonb_build_object('policyId',p.id,'policyVersion',p.policy_version,'privacyDocumentId',privacy.id,'privacyContentSha256',privacy.content_sha256,'delivery',m,
 'sha256',encode(extensions.digest(convert_to(jsonb_build_object('policy',to_jsonb(p),'rules',refs,'privacy',to_jsonb(privacy),'catalog',private.data_export_dataset_catalog())::text,'UTF8'),'sha256'),'hex'));
exception when data_exception then return null;
end $function$

CREATE OR REPLACE FUNCTION public.rpc_read_agreement_messages_page_v1(p_expected_user_id uuid, p_agreement_id uuid, p_limit integer DEFAULT 50, p_before_created_at timestamp with time zone DEFAULT NULL::timestamp with time zone, p_before_id uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
declare
  u uuid:=private.support_auth_v5(p_expected_user_id); ag public.agreements;
  selected jsonb; page_rows jsonb; photo_rows jsonb; messages jsonb;
  ids uuid[]; older jsonb:=null; has_older boolean;
begin
  ag:=private.agreement_photo_context_v5(u,p_agreement_id,null,false);
  -- The schema permits NULL participants (hard-delete FK/legacy states). The reused
  -- helper's NOT IN check is not sufficient for that state; require a positive match.
  if u is distinct from ag.requester_account_id and u is distinct from ag.worker_account_id then
    raise exception 'MEDIA_NOT_FOUND' using errcode='42501';
  end if;
  if p_limit is null or p_limit not between 1 and 50
    or (p_before_created_at is null)<>(p_before_id is null)
    or (p_before_created_at is not null and not isfinite(p_before_created_at)) then
    raise exception 'CHAT_CURSOR_INVALID' using errcode='22023';
  end if;
  if p_before_id is not null and not exists(select 1 from public.agreement_messages m
    where m.agreement_id=p_agreement_id and m.id=p_before_id and m.created_at=p_before_created_at) then
    raise exception 'CHAT_CURSOR_INVALID' using errcode='22023';
  end if;
  -- Read one extra row solely to determine whether an older page exists.
  -- The returned page is chronological; cursor comparisons retain microseconds.
  select coalesce(jsonb_agg(jsonb_build_object(
    'messageId',m.id,'agreementVersion',m.agreement_version,'senderAccountId',m.sender_account_id,
    'clientMessageId',m.client_message_id,'body',m.body,'createdAt',m.created_at,
    'kind',case when cardinality(m.photo_asset_ids)>0 then 'PHOTO' else 'TEXT' end,
    'mine',m.sender_account_id=u) order by m.created_at desc,m.id desc),'[]'::jsonb)
  into selected from (select x.* from public.agreement_messages x
    where x.agreement_id=p_agreement_id
      and (p_before_id is null or (x.created_at,x.id)<(p_before_created_at,p_before_id))
    order by x.created_at desc,x.id desc limit p_limit+1) m;
  has_older:=jsonb_array_length(selected)>p_limit;
  select coalesce(jsonb_agg(value order by ord desc),'[]'::jsonb),array_agg((value->>'messageId')::uuid order by ord desc)
    into page_rows,ids from jsonb_array_elements(selected) with ordinality r(value,ord) where ord<=p_limit;
  if cardinality(ids)>0 then
    -- Reuse the existing membership/link validation and ordered metadata allowlist.
    -- No private storage path, URL, input hash or unbound asset enters this page.
    photo_rows:=public.rpc_read_agreement_photo_messages_v5(u,p_agreement_id,ids)->'messages';
    select jsonb_agg(r.value||jsonb_build_object('photos',p.value->'photos') order by r.ord)
      into messages from jsonb_array_elements(page_rows) with ordinality r(value,ord)
      join jsonb_array_elements(photo_rows) p(value) on p.value->>'messageId'=r.value->>'messageId'
        and p.value->>'agreementVersion'=r.value->>'agreementVersion'
        and p.value->'clientMessageId'=r.value->'clientMessageId' and p.value->>'body'=r.value->>'body';
    if messages is null or jsonb_array_length(messages)<>cardinality(ids) then
      raise exception 'CHAT_MESSAGE_PROJECTION_CHANGED' using errcode='55000';
    end if;
    if has_older then older:=jsonb_build_object('createdAt',page_rows->0->'createdAt','messageId',page_rows->0->'messageId');end if;
  else messages:='[]'::jsonb;end if;
  perform private.support_auth_v5(u);
  return jsonb_build_object('schema','AGREEMENT_MESSAGES_PAGE_V1','accountId',u,'agreementId',p_agreement_id,
    'messages',messages,'olderCursor',older,'asOf',statement_timestamp(),'authoritative',true);
end
$function$

CREATE OR REPLACE FUNCTION public.rpc_read_agreement_message_window_v1(p_expected_user_id uuid, p_agreement_id uuid, p_target_message_id uuid, p_before_count integer DEFAULT 24, p_after_count integer DEFAULT 25)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
declare
  u uuid:=private.support_auth_v5(p_expected_user_id); ag public.agreements;
  target_at timestamptz; page_rows jsonb; photo_rows jsonb; messages jsonb; ids uuid[];
  has_before boolean; has_after boolean; before_cursor jsonb:=null; after_cursor jsonb:=null;
begin
  ag:=private.agreement_photo_context_v5(u,p_agreement_id,null,false);
  -- NULL participants are permitted by the schema; NOT IN alone is insufficient.
  if u is distinct from ag.requester_account_id and u is distinct from ag.worker_account_id then
    raise exception 'MEDIA_NOT_FOUND' using errcode='42501';
  end if;
  if p_before_count is null or p_after_count is null
    or p_before_count not between 0 and 49 or p_after_count not between 0 and 49 then
    raise exception 'CHAT_WINDOW_INVALID' using errcode='22023';
  end if;
  if p_before_count+p_after_count>49 then raise exception 'CHAT_WINDOW_INVALID' using errcode='22023';end if;
  select m.created_at into target_at from public.agreement_messages m
    where m.id=p_target_message_id and m.agreement_id=p_agreement_id;
  if not found then raise exception 'CHAT_MESSAGE_NOT_AVAILABLE' using errcode='42501';end if;

  -- Each side retains only its requested nearest rows plus one existence probe.
  -- All three branches use the same statement snapshot; the target is never trimmed.
  with before_rows as materialized (
    select m.* from public.agreement_messages m where m.agreement_id=p_agreement_id
      and (m.created_at,m.id)<(target_at,p_target_message_id)
    order by m.created_at desc,m.id desc limit p_before_count+1
  ), after_rows as materialized (
    select m.* from public.agreement_messages m where m.agreement_id=p_agreement_id
      and (m.created_at,m.id)>(target_at,p_target_message_id)
    order by m.created_at,m.id limit p_after_count+1
  ), window_rows as (
    (select * from before_rows order by created_at desc,id desc limit p_before_count)
    union all
    (select m.* from public.agreement_messages m where m.id=p_target_message_id
      and m.agreement_id=p_agreement_id and m.created_at=target_at)
    union all
    (select * from after_rows order by created_at,id limit p_after_count)
  )
  select coalesce(jsonb_agg(jsonb_build_object(
      'messageId',m.id,'agreementVersion',m.agreement_version,'senderAccountId',m.sender_account_id,
      'clientMessageId',m.client_message_id,'body',m.body,'createdAt',m.created_at,
      'kind',case when cardinality(m.photo_asset_ids)>0 then 'PHOTO' else 'TEXT' end,
      'mine',m.sender_account_id=u) order by m.created_at,m.id),'[]'::jsonb),
    array_agg(m.id order by m.created_at,m.id),
    (select count(*)>p_before_count from before_rows),(select count(*)>p_after_count from after_rows)
    into page_rows,ids,has_before,has_after from window_rows m;
  if cardinality(ids) is null or cardinality(ids)>50 or not p_target_message_id=any(ids) then
    raise exception 'CHAT_MESSAGE_NOT_AVAILABLE' using errcode='42501';
  end if;
  -- B3a's explicit TEXT/PHOTO projection and validated metadata identity join.
  photo_rows:=public.rpc_read_agreement_photo_messages_v5(u,p_agreement_id,ids)->'messages';
  select jsonb_agg(r.value||jsonb_build_object('photos',p.value->'photos') order by r.ord)
    into messages from jsonb_array_elements(page_rows) with ordinality r(value,ord)
    join jsonb_array_elements(photo_rows) p(value) on p.value->>'messageId'=r.value->>'messageId'
      and p.value->>'agreementVersion'=r.value->>'agreementVersion'
      and p.value->'clientMessageId'=r.value->'clientMessageId' and p.value->>'body'=r.value->>'body';
  if messages is null or jsonb_array_length(messages)<>cardinality(ids) then
    raise exception 'CHAT_MESSAGE_PROJECTION_CHANGED' using errcode='55000';
  end if;
  if has_before then before_cursor:=jsonb_build_object('createdAt',page_rows->0->'createdAt','messageId',page_rows->0->'messageId');end if;
  if has_after then after_cursor:=jsonb_build_object('createdAt',page_rows->-1->'createdAt','messageId',page_rows->-1->'messageId');end if;
  perform private.support_auth_v5(u);
  return jsonb_build_object('schema','AGREEMENT_MESSAGE_WINDOW_V1','accountId',u,'agreementId',p_agreement_id,
    'targetMessageId',p_target_message_id,'messages',messages,'beforeCursor',before_cursor,'afterCursor',after_cursor,
    'asOf',statement_timestamp(),'authoritative',true);
end
$function$
